int main(void)
{
  int n, i, sign = 1;
  double s = 0;
  scanf("%d", &n);
  for (i = 1; i <= n; i++) {
    s += sign * 1.0 / i;
    sign = -sign;
  }
  printf("%.4f\n", s);
  return 0;
}

