#include <stdio.h>
int main(void)
{
  int n, i, first = 1;
  scanf("%d", &n);
  printf("%d=", n);
  for (i = 2; n > 1; i++) {
    while (n % i == 0) {
      if (!first) printf("*");
      printf("%d", i);
      first = 0;
      n /= i;
    }
  }
  printf("\n");
  return 0;
}

#include <stdio.h>
int main(void)
{
  int x, count = 0, max = 0, sum = 0;
  scanf("%d", &x);
  while (x != 0) {
    count++;
    sum += x;
    if (count == 1 || x > max)
      max = x;
    scanf("%d", &x);
  }
  if (count == 0)
    printf("count=0\n");
  else {
    printf("count=%d max=%d ", count, max);
    printf("avg=%.2f\n", (double)sum / count);
  }
  return 0;
}
